// Une la ficha del calendario con el borrador del modelo.
const salida = [];
const fichas = $('Con mensaje y materia').all();
const respuestas = $input.all();
for (let i = 0; i < respuestas.length; i++) {
  const ficha = (fichas[i] || fichas[0]).json;
  const texto = respuestas[i].json?.content?.[0]?.text ?? '';
  salida.push({
    json: {
      id: ficha.id,
      fecha_publicacion: ficha.fecha_publicacion,
      canal: ficha.canal,
      tipo: ficha.tipo,
      mensaje_clave: ficha.mensaje_clave,
      materia_prima: ficha.materia_prima,
      borrador: texto.trim(),
      estado: 'revision',
      floja: texto.includes('PIEZA FLOJA') ? 'si' : 'no',
      falta_dato: texto.includes('FALTA DATO') ? 'si' : 'no',
    },
  });
}
return salida;

